use nix_rs::command::NixCmd;
use tokio::sync::OnceCell;

pub mod flake_template;

static NIXCMD: OnceCell<NixCmd> = OnceCell::const_new();

pub async fn nixcmd() -> &'static NixCmd {
    NIXCMD
        .get_or_init(|| async {
            NixCmd {
                refresh: true.into(),
                ..NixCmd::with_flakes().await.unwrap()
            }
        })
        .await
}

use std::path::PathBuf;

use clap::Parser;
use flakreate::{
    flake_template::{self, fileop::FileOp, FlakeTemplate},
    nixcmd,
};
use glob::{Pattern, PatternError};
use inquire::Select;
use nix_rs::flake::url::FlakeUrl;

#[derive(Parser, Debug)]
#[clap(author = "Sridhar Ratnakumar", version, about)]
/// Application configuration
struct Args {
    /// whether to be verbose
    #[arg(short = 'v')]
    verbose: bool,

    /// Flake template registry to use
    ///
    /// The flake attribute is treated as a glob pattern to select the
    /// particular template (or subset of templates) to use.
    #[arg(short = 't', default_value = "github:flake-parts/templates")]
    registry: FlakeUrl,

    /// Where to create the template
    #[arg()]
    path: PathBuf,
}

struct FlakeTemplateRegistry {
    pub flake_url: FlakeUrl,
    pub filter: Option<Pattern>,
}

impl FlakeTemplateRegistry {
    pub fn from_url(url: FlakeUrl) -> Result<Self, PatternError> {
        let (base, attr) = url.split_attr();
        Ok(FlakeTemplateRegistry {
            flake_url: base,
            filter: if attr.is_none() {
                None
            } else {
                Some(Pattern::new(&attr.get_name())?)
            },
        })
    }

    pub async fn load_and_select_template(&self) -> anyhow::Result<FlakeTemplate> {
        let term = console::Term::stdout();
        term.write_line(format!("Loading registry {}...", self.flake_url).as_str())?;
        let templates = flake_template::fetch(&self.flake_url).await?;
        term.clear_last_lines(1)?;
        println!("Loaded registry: {}", self.flake_url);
        // TODO: avoid duplicates (aliases)
        let filtered_templates = templates
            .iter()
            .filter(|template| {
                self.filter
                    .as_ref()
                    .map_or(true, |filter| filter.matches(&template.name))
            })
            .collect::<Vec<_>>();
        let template = if filtered_templates.len() == 1 {
            filtered_templates[0]
        } else {
            Select::new("Select a template", filtered_templates)
                .with_help_message("Choose a flake template to use")
                .prompt()?
        };
        println!("Selected template: {}", template);
        Ok(template.clone())
    }
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let args = Args::parse();
    if args.verbose {
        println!("DEBUG {args:?}");
    }
    println!(
        "Welcome to flakreate! Let's create your flake template at {:?}:",
        args.path
    );
    let template = FlakeTemplateRegistry::from_url(args.registry.clone())?
        .load_and_select_template()
        .await?;

    // Prompt for template parameters
    let param_values = template.prompt_replacements()?;

    let path = args.path.to_string_lossy();

    // Create the flake templatge
    let template_url = args.registry.with_attr(&template.name);
    println!("$ nix flake new {} -t {}", path, template_url);
    nixcmd()
        .await
        .run_with_args(&["flake", "new", &path, "-t", &template_url.0])
        .await?;

    // Do the actual replacement
    std::env::set_current_dir(args.path)?;
    for replace in param_values {
        FileOp::apply(&replace).await?;
    }
    Ok(())
}

use colored::Colorize;
use core::fmt;
use std::{
    collections::BTreeMap,
    fmt::{Display, Formatter},
};

use fileop::FileOp;
use nix_rs::{command::NixCmdError, flake::url::FlakeUrl};
use param::Param;
use serde::{Deserialize, Serialize};

use crate::nixcmd;

pub mod fileop;
pub mod param;

/// A Nix flake template
///
/// Defined per [this definition](https://nix.dev/manual/nix/2.22/command-ref/new-cli/nix3-flake-init#template-definitions) in the flake.
#[derive(Debug, Serialize, Deserialize, Clone)]
pub struct FlakeTemplate {
    #[serde(skip_deserializing)]
    pub name: String,

    #[serde(default)]
    pub tags: Vec<String>,

    pub description: String,

    pub path: String,

    #[serde(rename = "welcomeText")]
    pub welcome_text: Option<String>,

    pub params: Vec<Param>,
}

impl Display for FlakeTemplate {
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        if self.tags.is_empty() {
            write!(f, "{}", self.name)
        } else {
            write!(f, "{:<20} {}", self.name, self.tags.join(", ").dimmed())
        }
    }
}

impl FlakeTemplate {
    pub fn prompt_replacements(&self) -> anyhow::Result<Vec<Vec<FileOp>>> {
        self.params
            .iter()
            .map(|param| param.prompt_value())
            .collect()
    }
}

/// Fetch the templates defined in a flake
pub async fn fetch(url: &FlakeUrl) -> Result<Vec<FlakeTemplate>, NixCmdError> {
    let mut templates = nix_rs::flake::eval::nix_eval_attr_json::<BTreeMap<String, FlakeTemplate>>(
        nixcmd().await,
        &url.with_attr("templates"),
        false,
    )
    .await?;
    // Set 'name' field in each template
    for (name, template) in templates.iter_mut() {
        template.name.clone_from(name);
    }
    Ok(templates.values().cloned().collect())
}

use std::path::PathBuf;

use inquire::{Confirm, Text};
use serde::{Deserialize, Serialize};

use super::fileop::FileOp;

/// A parameter to be filled in by the user in a nix flake template path.
#[derive(Debug, Serialize, Deserialize, Clone)]
pub struct Param {
    /// Main message when prompting the user for input
    name: String,
    /// Message displayed at the line below the prompt.
    help: String,
    /// The default value used in the template files, that must be replaced by
    /// the user provided value (if it is different)
    default: Val,
    /// Short hint that describes the expected value of the input.
    placeholder: Option<String>,
    /// Files to do replacement on.
    files: Vec<PathBuf>,
    /// Whether the user must provide a value
    #[serde(default)]
    required: bool,
}

/// The `Param` type.
#[derive(Debug, Serialize, Deserialize, Clone)]
#[serde(untagged)]
enum Val {
    Str(String),
    Bool(bool),
}

impl Param {
    /// Prompt the user for a value for this parameter.
    ///
    /// Return a [`FileOp`] that knows how to apply the replacement.
    pub fn prompt_value(&self) -> anyhow::Result<Vec<FileOp>> {
        match self.default.clone() {
            Val::Str(v) => self.prompt_str(v),
            Val::Bool(v) => self.prompt_bool(v),
        }
    }
    pub fn prompt_bool(&self, default: bool) -> anyhow::Result<Vec<FileOp>> {
        let v = Confirm::new(&self.name)
            .with_help_message(&self.help)
            .with_default(default)
            .prompt()?;
        if v {
            // We expect the template to include all these conditional files by
            // default, so there's nothing to do.
            Ok(vec![])
        } else {
            let ops = self
                .files
                .iter()
                .map(|file| FileOp::PathDelete(file.clone()))
                .collect();
            Ok(ops)
        }
    }
    pub fn prompt_str(&self, default: String) -> anyhow::Result<Vec<FileOp>> {
        let to = Text::new(&self.name)
            .with_help_message(&self.help)
            .with_placeholder(self.placeholder.as_deref().unwrap_or(""))
            .with_default(&default)
            .prompt()?;
        let from = default.clone();
        let ops = FileOp::ops_for_replacing(&from, &to, &self.files);
        // TODO: return nothing if from == to
        Ok(ops)
    }
}

use std::path::PathBuf;

use serde::{Deserialize, Serialize};

/// An operation on a file part of the flake template
#[derive(Debug, Serialize, Deserialize, Clone)]
pub enum FileOp {
    /// Replace all occurrences of `from` with `to` in the file content
    ContentReplace(PathBuf, String, String),
    /// Rename the file to the given name
    FileRename(PathBuf, String),
    /// Delete the file or directory
    PathDelete(PathBuf),
}

impl FileOp {
    /// Return the list of [`FileOp`]s required to replace the placeholder
    /// `from` to an user-provided `to` across the given set of files.
    ///
    /// The placeholder is expected to be in both the file content and the file
    /// name.
    pub fn ops_for_replacing(from: &str, to: &str, files: &[PathBuf]) -> Vec<FileOp> {
        files
            .iter()
            .flat_map(|file| {
                let mut items: Vec<FileOp> = vec![];
                if to != from {
                    items.push(FileOp::ContentReplace(
                        file.clone(),
                        from.to_string(),
                        to.to_string(),
                    ));
                    if file.to_string_lossy().contains(from) {
                        items.push(FileOp::FileRename(
                            file.clone(),
                            file.to_string_lossy().replace(from, to),
                        ))
                    }
                }
                items
            })
            .collect()
    }

    pub async fn apply(ops: &[Self]) -> anyhow::Result<()> {
        // TODO: Refactor the LLM generated code below
        // TODO: Append thesae paths to base dir
        for op in ops {
            match op {
                FileOp::ContentReplace(file, from, to) => {
                    let content = tokio::fs::read_to_string(file).await?;
                    let content = content.replace(from, to);
                    println!("replace: {} : {} -> {}", file.display(), from, to);
                    tokio::fs::write(file, content).await?;
                }
                FileOp::FileRename(file, new_name) => {
                    println!("rename: {} -> {}", file.display(), new_name);
                    tokio::fs::rename(file, new_name).await?;
                }
                FileOp::PathDelete(path) => {
                    println!("delete: {}", path.display());
                    // FIXME: Careful not to delete anything outside of base dir!
                    tokio::fs::remove_dir_all(path).await?;
                }
            }
        }
        Ok(())
    }
}
